def main():
    import glob
    for fname, extras in EXTRA.items():
        with open(fname, encoding='utf-8') as f:
            content = f.read()
        lines = content.split('\n')
        new_lines = []
        for line in lines:
            if line.strip() == ']' and not new_lines[-1].strip().startswith('@'):
                for extra in extras:
                    new_lines.append(f'"{extra}",')
                new_lines.append(line)
            else:
                new_lines.append(line)
        new_content = '\n'.join(new_lines)
        with open(fname, 'w', encoding='utf-8') as f:
            f.write(new_content)
        print(f'{fname}: added {len(extras)} paragraphs')

if __name__ == '__main__':
    main()
